    q=r;q.schedule.scheduling.resources[0].recoveryPicoseconds=1000;q.schedule.scheduling.dependencies={{"a","b",5000}};q.schedule.scheduling.resources[0].unavailableIntervals={{0,20000},{55000,70000}};auto combined=timeMemoryTests(d,q);need(combined&&combined->timeline.durationPicoseconds==86007&&combined->timeline.resourceWaitPicoseconds==2000&&combined->timeline.dependencyWaitPicoseconds==4000&&combined->timeline.availabilityWaitPicoseconds==31986,"recovery dependency availability attribution");
